L27_1 = "影片中，西羅科娃襲擊了研究員以攝取血液，因此我認為這是一種<color=#ffd34c>進食</color>行為。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "视频中，西罗科娃袭击了研究员以摄取血液，因此我认为这是一种<color=#ffd34c>进食</color>行为。"
L26_1.m_Talk_SCN = L27_1
