L28_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L29_1 = "과연. 그 두 가지 단서로 예니카 양이 자신의 흡혈 행위가 보여지는 것에 수치심을 느낀다는 걸 알아냈군."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "なるほど。その2つの手がかりから、イェニカ君が自分の吸血行為を他人に見られることに恥を感じていることがわかったんだな。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I see. With those two clues, you found out that Yanikka feels ashamed of her bloodsucking behavior being seen."
L28_1.m_Talk_ENG = L29_1
L29_1 = "所以，透過這兩個線索，你發現耶妮卡羞於讓他人看見自己的吸血行為。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "所以，通过这两个线索，你发现耶妮卡羞于让他人看见自己的吸血行为。"
