L6_1 = "네가 기억을 전승하고 새로운 기회를 만들어내도, 난 다시 늑대를 지키기 위해 이 힘을 쓰고 말 거다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "お前が記憶を伝承して新しいチャンスを作り出すとしても、私はまたオオカミを守るためにこの力を使ってしまうだろう。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Even if you transfer your memories and create a new opportunity, I will end up using my powers again to protect the Wolf."
L5_1.m_Talk_ENG = L6_1
L6_1 = "即使你傳走了記憶並創造了新的機會，我也會再次使用這股力量來保護狼的。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "即使你传走了记忆并创造了新的机会，我也会再次使用这股力量来保护狼的。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Even if you transfer your memories and create a new opportunity, I will end up using my powers again to protect the Wolf."
