L21_1 = "내가 이곳에 남으면, 내 힘이 기둥이 되어 무너지는 세계를 지탱할 수 있어."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "私がここに残れば、私の力が柱となって崩れていく世界を支えることができる。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "If I stay here, my power will become a pillar to support the collapsing world."
L20_1.m_Talk_ENG = L21_1
L21_1 = "如果我留在這裡，那我的力量將成為支柱，支撐住崩潰的世界。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "如果我留在这里，那我的力量将成为支柱，支撑住崩溃的世界。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "If I stay here, my power will become a pillar to support the collapsing world."
L20_1.m_Talk_DEU = L21_1
L21_1 = "If I stay here, my power will become a pillar to support the collapsing world."
