L22_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L23_1 = "하지만 클리포트게임을 패배한 시점에서, 이 세계의 파멸은 확정된 거야."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "だがクリフォトゲームで負けた時点で、この世界の破滅は確定されたんだ。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "But since we lost the Qliphoth Game, this world is guaranteed for annihilation."
L22_1.m_Talk_ENG = L23_1
L23_1 = "但是在逆卡巴拉遊戲失敗的那一刻，這個世界的毀滅就已經註定了。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "但是在神圣战役失败的那一刻，这个世界的毁灭就已经注定了。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "But since we lost the Qliphoth Game, this world is guaranteed for annihilation."
L22_1.m_Talk_DEU = L23_1
L23_1 = "But since we lost the Qliphoth Game, this world is guaranteed for annihilation."
