L23_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L24_1 = "여기서 자네의 힘을 전부 바친다고 해도, 결국 멸망은 피하지 못한다는 걸 알잖나."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "ここで君の力をすべて捧げるとしても、結局滅亡は避けられないということをわかっているだろう？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Even if you give all your strength here, you know that it won't prevent doom."
L23_1.m_Talk_ENG = L24_1
L24_1 = "即使你在這裡獻出全部力量，最後也無法避免它的滅亡，你是知道的。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "即使你在这里献出全部力量，最终也无法避免它的灭亡，你是知道的。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Even if you give all your strength here, you know that it won't prevent doom."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Even if you give all your strength here, you know that it won't prevent doom."
L23_1.m_Talk_FRA = L24_1
