L27_1 = "HILDE_FENRIR_ADMIN_PAST"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L26_1.m_bCharPinup = true
L27_1 = "현실 뒤편에 모두를 남겨두고 떠나는 것도, 그녀가 죽는 걸 바라만 보는 것도… 더는 하고 싶지 않아."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "現実の裏側にみんなを残して行くのも、彼女が死ぬのを見ているだけなのも……もううんざりだ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Leaving everyone behind in the other face of the Normalside, and watching her die... I don't want to do this anymore."
L26_1.m_Talk_ENG = L27_1
L27_1 = "無論是拋下所有人離開這個現實世界，還是眼睜睜看著她死去……我都不想再這樣了。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "无论是抛下所有人离开这个现实世界，还是眼睁睁看着她死去……我都不想再这样了。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Leaving everyone behind in the other face of the Normalside, and watching her die... I don't want to do this anymore."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Leaving everyone behind in the other face of the Normalside, and watching her die... I don't want to do this anymore."
L26_1.m_Talk_FRA = L27_1
