L29_1 = "EP12_ACT2_INTERLUDE9@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 553
L28_1.m_CutScenStrID = "EP12_ACT2_INTERLUDE9"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L29_1 = "실패하더라도 계속 시도해야만 해. 그래야만 언젠가 이 순환을 멈출 수 있어."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "失敗しても続けなければならない。そうでなければ、この循環は終わらないんだ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "We must keep trying, even if we fail. That is how we can break the cycle one day."
L28_1.m_Talk_ENG = L29_1
L29_1 = "即使失敗也要繼續嘗試。只有這樣，才能有一天終止這個迴圈。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "即使失败也要继续尝试。只有这样，才能有一天终止这个循环。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "We must keep trying, even if we fail. That is how we can break the cycle one day."
L28_1.m_Talk_DEU = L29_1
L29_1 = "We must keep trying, even if we fail. That is how we can break the cycle one day."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP12_ACT2_INTERLUDE9@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 553
L29_1.m_CutScenStrID = "EP12_ACT2_INTERLUDE9"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L30_1 = "우리가 포기해버리면, 늑대도, 대적자도… 탐미엘이 만든 굴레를 영원히 벗어나지 못할 테니."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "私たちが諦めてしまえば、オオカミも敵対者も……タミエルが作ったしがらみから永遠に逃げられないはずだからな。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "If we give up, the Wolf and the Antagonist... will never be able to escape the bounds Tammiel has created."
L29_1.m_Talk_ENG = L30_1
L30_1 = "如果我們放棄了，不論是狼，還是敵對者……都將永遠無法擺脫塔米爾製造的枷鎖。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "如果我们放弃了，不论是狼，还是敌对者……都将永远无法摆脱塔米尔制造的枷锁。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "If we give up, the Wolf and the Antagonist... will never be able to escape the bounds Tammiel has created."
L29_1.m_Talk_DEU = L30_1
L30_1 = "If we give up, the Wolf and the Antagonist... will never be able to escape the bounds Tammiel has created."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
