L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L33_1 = "운명을 벗어날 수 없다면, 그 운명을 기억과 함께 봉인하면 돼."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "運命から逃げられないのなら、その運命を記憶とともに封印すればいい。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "If you can't escape your fate, then we can seal it with your memories."
L32_1.m_Talk_ENG = L33_1
L33_1 = "如果無法逃避命運，那就將你的命運與記憶一同封印吧。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "如果无法逃避命运，那就将你的命运与记忆一同封印吧。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "If you can't escape your fate, then we can seal it with your memories."
L32_1.m_Talk_DEU = L33_1
L33_1 = "If you can't escape your fate, then we can seal it with your memories."
