L31_1 = "내가 가짜인지 의심된다면, 우리만 아는 비밀 몇 가지를 말해줄 순 있네만."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "私が偽物ではないのか疑っているのなら、私たちだけが知っている秘密をいくつか話してやれるんだが。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "If you're doubting my identity, I'm happy to tell you a few secrets only we know about."
