L32_1.m_fTalkTime = 0.03
L33_1 = "ふん、こんなところに現われてくだらないことを言う人間はそうそういない。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Hmph. There aren't a lot of people who'd start talking nonsense after showing up at a place like this."
