L36_1.m_bCharPinup = true
L37_1 = "그 쥐구멍만한 환기구에 낀 채로 날 구하겠다고?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "そんな小さな換気口に挟まった状態で、私を助けるだと？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "How are you going to rescue me when you're stuck inside that tiny vent?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "你是說，你打算卡在那個老鼠洞一樣的通風口裡救我？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "你是说，你打算卡在那个老鼠洞一样的通风口里救我？"
