L38_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L39_1 = "보안에 빈틈이 없더군. 지금으로선 이렇게 대화라도 나누는 게 최선이라네."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "セキュリティに抜かりがなくてな。今はこうやって会話をするだけでも精一杯だ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Their security is airtight. The best we can do right now is to have a conversation like this."
L38_1.m_Talk_ENG = L39_1
L39_1 = "他們的安全太嚴密了，現在這樣對話已經是最好的選擇了。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "他们的安保太严了。现在这样对话已经是最好的选择了。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Their security is airtight. The best we can do right now is to have a conversation like this."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Their security is airtight. The best we can do right now is to have a conversation like this."
