L40_1 = "자넬 데리고 나갈 방법은 이 감옥을 살펴본 뒤에 고민해봐야지."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "君を連れて出る方法は、この牢獄を調べてから考えてみよう。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I'll think of a way to get you out after I look around this prison."
L39_1.m_Talk_ENG = L40_1
L40_1 = "至於帶你出去的方法，得先看看這個監獄再說。"
L39_1.m_Talk_TWN = L40_1
