L41_1 = "그래서, 살펴본 소감은 어떻지? 우리 모두 무사히 탈출할 것 같나?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "それで、調べた感想はどうだ？　私たち全員無事脱出できそうか？"
