L43_1 = "君と一緒に脱出するか、全員で捕まるか。どちらかだろうな。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I guess we'll escape altogether, or get caught altogether."
L42_1.m_Talk_ENG = L43_1
L43_1 = "要麼一起逃跑，要麼一起被抓。總之就是其中之一。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "要么一起逃跑，要么一起被抓。总之就是其中之一。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "I guess we'll escape altogether, or get caught altogether."
L42_1.m_Talk_DEU = L43_1
L43_1 = "I guess we'll escape altogether, or get caught altogether."
L42_1.m_Talk_FRA = L43_1
