L45_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L46_1 = "난 언제나 노력파였다네. 확신은 경험과 근거에서 나오는 것일 뿐이야."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "私はいつも努力家だったのさ。確信は経験と根拠から出てくるだけだ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I've always put the effort in. Certainty is something that comes from experience and reason."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我可一直都是個努力派。信心只來自於經驗和依據。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "呵呵，我可一直都是个努力派。我的信心一直只来自于经验和依据。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "I've always put the effort in. Certainty is something that comes from experience and reason."
L45_1.m_Talk_DEU = L46_1
L46_1 = "I've always put the effort in. Certainty is something that comes from experience and reason."
