L48_1 = "어렴풋한 기억으론, 녀석들이 내 몸에 뭔가를 심어뒀다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "記憶はおぼろげだが、やつらが私の体に何かを埋め込んだ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "From what I recall, they implanted something in my body."
L47_1.m_Talk_ENG = L48_1
L48_1 = "我依稀記得，他們在我體內植入了什麼東西。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "我依稀记得，他们在我体内植入了什么东西。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "From what I recall, they implanted something in my body."
L47_1.m_Talk_DEU = L48_1
L48_1 = "From what I recall, they implanted something in my body."
