L49_1 = "추적기일 수도 있고, 탈출하려는 순간 거대한 폭발을 일으키는 폭탄일지도 몰라."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "追跡装置かもしれないし、脱出しようとする瞬間に巨大は爆発を起こす爆弾かもしれない。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "It could be a tracker, or maybe a bomb that goes off the second I try to escape."
L48_1.m_Talk_ENG = L49_1
L49_1 = "可能是追蹤器，也可能是在我試圖逃脫的瞬間引爆的炸彈。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "可能是追踪器，也可能是在我试图逃脱的瞬间引爆的炸弹。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "It could be a tracker, or maybe a bomb that goes off the second I try to escape."
L48_1.m_Talk_DEU = L49_1
