L3_1 = "관건은 날 구하려고 실패의 위험을 감수할 필요는 없단 거다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "要するに、私を助けるために失敗する危険を冒す必要はないということだ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "The main point is that you don't have to risk failing to save me."
L2_1.m_Talk_ENG = L3_1
L3_1 = "關鍵是你沒必要冒著失敗的風險來救我。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "关键是你没必要冒着失败的风险来救我。"
