L4_1 = "녀석이 날 가뒀다는 건, 적어도 당장은 해칠 생각이 없단 뜻이니까."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "やつが私を閉じ込めたということは、少なくとも今すぐ私に害をなすつもりはないという意味だから。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "The fact that they locked me up means that they have no intention of harming me. Or at least, not right away."
L3_1.m_Talk_ENG = L4_1
L4_1 = "他們把我關起來，至少說明暫時沒有傷害我的打算。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "他们把我关起来，至少说明暂时没有伤害我的打算。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "The fact that they locked me up means that they have no intention of harming me. Or at least, not right away."
L3_1.m_Talk_DEU = L4_1
