L8_1.m_CharStrID = L9_1
L9_1 = "패러독스가 혼자 우물로 뛰어들었어. 합의체 녀석들에게 쫓겨 동앗줄을 설치할 새도 없이 빠졌지."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "パラドックスが1人で井戸に飛び込んだ。合意体のやつらに追われてロープを設置する間もなく落ちたんだ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Paradox jumped into the Well by herself. She was chased by the Northern Union jerks, and fell in without being able to set up the Straw Rope."
L8_1.m_Talk_ENG = L9_1
L9_1 = "悖論一個人跳進了井裡。被北方和議會的人追著，連綁好繩的時間都沒有就掉了下去。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "悖论一个人跳进了井里。被北方联盟的人追着，连绑好“绳”的时间都没有就掉了下去。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Paradox jumped into the Well by herself. She was chased by the Northern Union jerks, and fell in without being able to set up the Straw Rope."
