L13_1.m_fTalkTime = 0.03
L14_1 = "問題はやつにロープがないと私の記憶を取り戻しても戻ってくる方法がないということだ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "The problem is that, without the Straw Rope, there is also no way for her to return, even if she retrieves my memories."
L13_1.m_Talk_ENG = L14_1
L14_1 = "問題是，如果她沒有繩，即使找回了我的記憶，也沒有辦法回來。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "问题是，如果她没有绳，即使找回了我的记忆，也没有办法回来。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "The problem is that, without the Straw Rope, there is also no way for her to return, even if she retrieves my memories."
